      ngModule: NgduxListStateModule,
      providers: [
        { provide: LIST_SERVICES, multi: true, useClass: config.service },
        {
          provide: LIST_NOTIFICATION_SERVICES,
          multi: true,
          useClass: config.notificationService || NotificationServicePlaceholder
        }
      ]
    };
  }
}

